    uniform = {}
    for row in grid:
        if len(set(row)) == 1:
            uniform[row[0]] = uniform.get(row[0], 0) + 1
    for j in range(w):
        col = [grid[i][j] for i in range(h)]
        if len(set(col)) == 1:
            uniform[col[0]] = uniform.get(col[0], 0) + 1
    sep = max(uniform, key=uniform.get)

    row_lines = [i for i, row in enumerate(grid) if all(x == sep for x in row)]
    col_lines = [j for j in range(w) if all(grid[i][j] == sep for i in range(h))]
    rb = [-1] + row_lines + [h]
    cb = [-1] + col_lines + [w]

