def transform(grid):
    h, w = len(grid), len(grid[0])

    # The full-width and full-height lines are panel separators.
    sep = max(
        set(sum(grid, [])),
        key=lambda color: sum(all(v == color for v in row) for row in grid)
                         + sum(all(grid[i][j] == color for i in range(h)) for j in range(w))
    )
    row_lines = [i for i, row in enumerate(grid) if all(v == sep for v in row)]
    col_lines = [j for j in range(w) if all(grid[i][j] == sep for i in range(h))]

    # The most common non-separator color is the panel background.
    counts = {}
    for row in grid:
        for v in row:
            if v != sep:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    marker = next(v for v in counts if v != bg)

    rb = [-1] + row_lines + [h]
    cb = [-1] + col_lines + [w]
    result = []
    for a, b in zip(rb, rb[1:]):
        out_row = []
        for c, d in zip(cb, cb[1:]):
            n = sum(grid[i][j] == marker
                    for i in range(a + 1, b) for j in range(c + 1, d))
            out_row.append(1 if n >= 2 else bg)
        result.append(out_row)
    return result
